p.write_text('''def transform(grid):
    out=[r[:] for r in grid]
    w=len(grid[0])
    full={r[0] for r in grid if all(x==r[0] for x in r)}
    for i,row in enumerate(grid):
        if not row or row[0] not in full: continue
        k=1
        while k<w and row[k]==row[0]: k+=1
        if k<w:
            # A matching full-width row elsewhere supplies the expected extent.
            if any(j!=i and all(x==row[0] for x in grid[j]) for j in range(len(grid))):
                for x in range(k,w): out[i][x]=1
    # Same rule for repeated patterned bands without a solid row: align the two bands.
    fg_counts={v:sum(r.count(v) for r in grid) for r in set(x for r in grid for x in r)}
    bg=max(fg_counts,key=fg_counts.get)
    fg=[v for v in fg_counts if v!=bg]
    if len(fg)==1:
        active=[i for i,r in enumerate(grid) if fg[0] in r]
        if len(active)>=2 and len(active)%2==0:
            mid=len(active)//2
            for i,j in zip(active[:mid],active[mid:]):
                n1=max((k+1 for k,x in enumerate(grid[i]) if x==fg[0]),default=0)
                n2=max((k+1 for k,x in enumerate(grid[j]) if x==fg[0]),default=0)
                if n1>n2 and all(x==bg for x in grid[j][n2:n1]):
                    for k in range(n2,n1): out[j][k]=1
    return out
''')
